function tbl(headers, rows){
  var h = '<table class="minitable"><tr>'+headers.map(x=>'<th>'+x+'</th>').join('')+'</tr>';
  rows.forEach(r=>{ h+='<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>'; });
  h += '</table>';
  return h;
}
